const sourceIds=['s'],base=(type,title)=>({schema:'pm-chart-v1',id:type,type,title,evidenceStatus:'测试数据',sources:[{id:'s',title:'合成验收数据'}],encoding:{},data:[]});
export function auditCharts(){
 const bar=base('bar','多系列横向条形图：长名称与零值');bar.encoding={x:{field:'value',scale:'quantitative'},y:{field:'name',scale:'category',categories:['独居上班族的长名称用户群体','移动端轻度使用群体']},series:{field:'group'}};bar.data=[{name:bar.encoding.y.categories[0],group:'方案甲',value:3,sourceIds},{name:bar.encoding.y.categories[0],group:'方案乙',value:0,sourceIds},{name:bar.encoding.y.categories[1],group:'方案甲',value:-2,sourceIds},{name:bar.encoding.y.categories[1],group:'方案乙',value:5,sourceIds}];
 const line=base('line','时间折线：缺失值保留断点');line.encoding={x:{field:'date',scale:'time'},y:{field:'value',scale:'quantitative'}};line.data=[{date:'2025-01-01',value:3,sourceIds},{date:'2025-01-02',value:null,sourceIds},{date:'2025-01-03',value:7,sourceIds}];
 const pie=base('pie','饼图：对象形式字段与零值');pie.encoding={value:{field:'value'},label:{field:'name'}};pie.data=[{name:'甲类',value:2,sourceIds},{name:'乙类',value:5,sourceIds},{name:'零值类别',value:0,sourceIds}];
 const funnel=base('funnel','漏斗：保持阶段顺序');funnel.encoding={value:'value',label:'name'};funnel.data=[{name:'访问',value:100,sourceIds},{name:'注册',value:40,sourceIds},{name:'付费',value:8,sourceIds}];
 const matrix=base('matrix','定性矩阵：同位置的两个条目');matrix.encoding={x:{field:'x',scale:'ordinal',categories:['低','中','高'],label:'发生频率'},y:{field:'y',scale:'ordinal',categories:['低','中','高'],label:'影响程度'},label:{field:'name'}};matrix.data=[{name:'痛点一',x:'高',y:'高',sourceIds},{name:'痛点二',x:'高',y:'高',sourceIds},{name:'痛点三',x:'低',y:'中',sourceIds}];
 const scatter=base('scatter','数值散点图：原点和负值');scatter.encoding={x:{field:'x',scale:'quantitative'},y:{field:'y',scale:'quantitative'},label:{field:'name'}};scatter.data=[{name:'原点',x:0,y:0,sourceIds},{name:'方案甲',x:-2,y:5,sourceIds},{name:'方案乙',x:4,y:3,sourceIds}];
 const heatmap=base('heatmap','热力图：对象形式数值字段');heatmap.encoding={x:{field:'dimension',scale:'category',categories:['记忆连续','创作自由','安装门槛低','日常陪伴','价格透明']},y:{field:'name',scale:'category',categories:['软件方案','桌面方案','自建角色']},value:{field:'rating',label:'定性评分'}};heatmap.data=heatmap.encoding.y.categories.flatMap((name,y)=>heatmap.encoding.x.categories.map((dimension,x)=>({name,dimension,rating:(x+y)%3+1,sourceIds})));
 return [bar,line,pie,funnel,matrix,scatter,heatmap];
}
export const auditDiagrams=[`flowchart LR\n A["产品想法"] --> B{"材料充分？"}\n B -->|是| C["用户分析"]\n B -->|否| D["补充材料"]\n D --> B`,`sequenceDiagram\n participant U as 用户\n participant A as 助手\n U->>A: 提交研究目标\n A-->>U: 确认研究范围\n U->>A: 确认并继续`,`stateDiagram-v2\n state "待处理" as Pending\n state "处理中" as Running\n state "已完成" as Done\n [*] --> Pending\n Pending --> Running\n Running --> Done\n Done --> [*]`,`gantt\n title 研究任务排期\n dateFormat YYYY-MM-DD\n section 调研\n 收集资料 :a, 2025-01-01, 2d\n 用户分析 :after a, 3d`];
